import sqlite3, json
db=sqlite3.connect("file:/Users/jbotts/frus-analysis/c3/frus-copy-2026-10-25.db?mode=ro",uri=True)
db.execute("create temp table setA(volume_id text, document_id text)")
db.executemany("insert into setA values(?,?)",[tuple(l.rstrip("\n").split("\t")[:2]) for l in open("setA.tsv")])
print("presidentialLibrary anchors:")
for r in db.execute("select e.repository,substr(e.collection,1,50),count(*),count(distinct e.volume_id||'/'||e.document_id) from external_citations e join setA a on a.volume_id=e.volume_id and a.document_id=e.document_id where e.anchor='presidentialLibrary' group by 1,2 order by 3 desc limit 14"): print(r)
print("centralFileClass anchors by decimal_class:")
for r in db.execute("select e.decimal_class,count(*),count(distinct e.volume_id||'/'||e.document_id) from external_citations e join setA a on a.volume_id=e.volume_id and a.document_id=e.document_id where e.anchor='centralFileClass' group by 1 order by 2 desc limit 14"): print(r)
print("sample raw_text for lot 66D95:")
for r in db.execute("select e.volume_id,e.document_id,substr(e.raw_text,1,200) from external_citations e join setA a on a.volume_id=e.volume_id and a.document_id=e.document_id where e.lot_file_norm='66D95' limit 3"): print(r)
print("distinct volumes cited from:",db.execute("select count(distinct e.volume_id) from external_citations e join setA a on a.volume_id=e.volume_id and a.document_id=e.document_id").fetchone())
print("setA docs with >=1 external citation:",db.execute("select count(distinct e.volume_id||'/'||e.document_id) from external_citations e join setA a on a.volume_id=e.volume_id and a.document_id=e.document_id").fetchone(), "of", db.execute("select count(*) from setA").fetchone())
pl=json.load(open("/Applications/FRUS Explorer.app/Contents/Resources/presidential-library-catalog.json"))
print(list(pl.keys()))
